from pathlib import Path
import json,difflib
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
paths={'md':'content/isc2-cc-2026/reading/domain-2.md','diagram':'js/core/diagram-generator.js'}
original={k:(OUT/('before-'+Path(v).name)).read_bytes().decode()for k,v in paths.items()};text=dict(original);changes=[]
for k,p in paths.items():assert(ROOT/p).read_bytes().decode()==original[k],'Intervening production edit: '+p
def replace(k,old,new,finding):
    assert text[k].count(old)==1,(k,old)
    changes.append({'finding':finding,'path':paths[k],'before':old,'after':new,'entryLine':original[k][:original[k].index(old)].count('\n')+1})
    text[k]=text[k].replace(old,new,1)
replace('md','ในการวางแผนกู้คืนระบบ IT องค์กรต้องกำหนดเป้าหมายเชิงเวลา 2 ตัวชี้วัดสำคัญ:\n','ในการวางแผนกู้คืนระบบ IT องค์กรต้องกำหนดเป้าหมายเชิงเวลา 2 ตัวชี้วัดสำคัญ:\n\n**สมมติฐานของภาพ (Illustrative assumptions):** ภาพสมมติว่ามีจุดสำรองที่กู้คืนได้เวลา 16:30 น. และเกิดเหตุเวลา 17:00 น.; จุดสำรองนี้ตรงกับขอบเขต RPO 30 นาทีในตัวอย่าง ส่วน 18:00 น. เป็นเป้าหมาย RTO 1 ชั่วโมง ไม่ใช่ผลกู้คืนที่ทดสอบแล้ว / The illustration assumes a recoverable 16:30 backup and a 17:00 outage. That backup coincides with the example’s 30-minute RPO boundary; 18:00 is the one-hour RTO target, not a tested recovery outcome.\n','ACC-D2-01')
replace('md','- **สูตรความสัมพันธ์แม่บทสำหรับห้องสอบ:**\n  **MTD &ge; RTO + WRT**\n  *(หาก RTO + WRT &gt; MTD หมายความว่าธุรกิจจะได้รับความเสียหายวิกฤตเกินระดับที่องค์กรจะอยู่รอดได้)*','- **แบบจำลองวางแผนอย่างง่าย (Simplified planning model):**\n  **MTD &ge; RTO + WRT**\n  ในแบบจำลองนี้ RTO นับจากเริ่มหยุดชะงักจนระบบ IT พร้อมใช้งาน แล้ว WRT นับต่อจนธุรกิจกลับมาดำเนินงาน โดยสมมติให้สองช่วงไม่ซ้อนทับกัน; กิจกรรมจริงอาจซ้อนทับกันได้ / Here, RTO runs from disruption to IT readiness, followed by WRT until business resumes. The model assumes non-overlapping intervals; actual activities may overlap.\n  *หากผลรวมเกิน MTD แผนนี้จัดสรรเวลาเกินช่วงหยุดชะงักที่ธุรกิจยอมรับ ต้องทบทวนแผน; การหยุดชะงักจริงเกิน MTD ไม่ได้หมายความว่าองค์กรจะอยู่รอดไม่ได้เสมอไป / If the sum exceeds MTD, the plan exceeds the business downtime tolerance and needs review. An actual outage beyond MTD does not inevitably mean organizational failure.*','ACC-D2-01')
replace('md','<div class="reading-semantic-diagram" data-diagram="effectivenessHierarchy"></div>','**รอบอัปเดต (Refresh cadence):** Dashboard อาจอัปเดตเป็นระยะหรือใกล้เวลาจริง ขึ้นอยู่กับการเก็บข้อมูลและการรายงาน ควรตรวจเวลาอัปเดตของข้อมูล / A dashboard may refresh periodically or near real time, depending on data collection and reporting; check when its data was updated.\n\n<div class="reading-semantic-diagram" data-diagram="effectivenessHierarchy"></div>','ACC-D2-02')
replace('md','| **Dashboard** | "Real-time", "Operational view", "Visual representation" | แสดงภาพรวมสถานะปัจจุบันผ่านชาร์ต/กราฟสำหรับการเฝ้าระวังประจำวัน | หน้าจอ SOC แสดงสถานะการโจมตีและการแจ้งเตือนความปลอดภัยแบบเรียลไทม์ |','| **Dashboard** | "Refresh cadence varies", "Operational view", "Visual representation" | แสดงภาพรวมผ่านชาร์ต/กราฟสำหรับการเฝ้าระวังประจำวัน โดยความสดของข้อมูลขึ้นกับรอบอัปเดต (Data freshness depends on refresh cadence) | ตัวอย่างหน้าจอ SOC ที่ตั้งค่าให้อัปเดตใกล้เวลาจริง (Illustrative near-real-time SOC view) |','ACC-D2-02')
replace('md','<div class="reading-distinction-desc">Visualize — นำเสนอข้อมูลภาพรวมและแนวโน้มแบบ Real-time</div>','<div class="reading-distinction-desc">Visualize — นำเสนอภาพรวมและแนวโน้มตามรอบอัปเดต (Periodic / near-real-time)</div>','ACC-D2-02')
replace('diagram','<text x="56" y="158" class="diag-text-sub">ภาพรวมสถานะความปลอดภัยแบบเรียลไทม์</text>','<text x="56" y="158" class="diag-text-sub">ภาพรวมตามรอบอัปเดต (Refresh cadence)</text>','ACC-D2-02')
replace('diagram','<text x="130" y="358" class="diag-text-sub">ค่าดิบที่วัดได้เชิงปริมาณ (Quantifiable Raw Value) ซึ่งเป็นรากฐานข้อมูลของการวัดผลทุกระดับ</text>','<text x="130" y="358" class="diag-text-sub">ค่าที่กำหนดและวัดได้ (Defined measurable value)</text>','ACC-D2-02')
replace('diagram','<p class="reading-mob-tier-desc"><strong>Dashboard:</strong> แสดงผลกราฟิกแบบ Real-time &middot; <strong>Scorecard:</strong> เปรียบเทียบผลงานจริง (Actual) เทียบเป้าหมาย (Targets) เพื่อชี้วัด Gaps</p>','<p class="reading-mob-tier-desc"><strong>Dashboard:</strong> แสดงผลกราฟิกตามรอบอัปเดต (Periodic / near-real-time) &middot; <strong>Scorecard:</strong> เปรียบเทียบผลงานจริง (Actual) เทียบเป้าหมาย (Targets) เพื่อชี้วัด Gaps</p>','ACC-D2-02')
replace('diagram','<p class="reading-mob-tier-desc">ค่าดิบที่วัดได้เชิงปริมาณ (Quantifiable Raw Value) ซึ่งเป็นรากฐานข้อมูลของการวัดผลทุกระดับ &middot; คุณสมบัติที่ดี: Relevant (ตรงประเด็น), Measurable (วัดได้จริง), Consistent (วัดซ้ำได้ผลสม่ำเสมอ)</p>','<p class="reading-mob-tier-desc">ค่าที่กำหนดและวัดได้ (Defined measurable value): จำนวน ร้อยละ อัตราส่วน หรือค่าเฉลี่ย (count, percentage, ratio or average) &middot; คุณสมบัติที่ดี: Relevant (ตรงประเด็น), Measurable (วัดได้จริง), Consistent (วัดซ้ำได้ผลสม่ำเสมอ)</p>','ACC-D2-02')
for k,p in paths.items():(ROOT/p).write_bytes(text[k].encode())
(OUT/'exact-changes.json').write_bytes((json.dumps(changes,ensure_ascii=False,indent=2)+'\n').encode())
(OUT/'production-diff.txt').write_bytes(''.join(''.join(difflib.unified_diff(original[k].splitlines(True),text[k].splitlines(True),fromfile='entry/'+p,tofile='after/'+p))for k,p in paths.items()).encode())
print('Applied',len(changes),'exact spans across two production files')
